// Get all items from the Read/Write Files node
const items = $input.all();

// Extract just the filenames and join them with commas
const filenames = items.map(item => item.json.fileName).join(', ');

return {
  json: {
    filenames: filenames
  }
};

// Grab the comma-separated string from your previous code node
const filenamesString = $input.first().json.filenames || "";

// Split the string into an array, trim extra spaces, and remove any empty items
const fileArray = filenamesString.split(',').map(item => item.trim()).filter(item => item !== "");

// Map the filenames into the exact 'values' array format n8n expects
const dropdownValues = fileArray.map(filename => {
  return {
    option: filename
  };
});

// Add the "New Product" option to the very beginning of the list
dropdownValues.unshift({
  option: "New Product"
});

// Construct the complete form field JSON using n8n's strict schema
const formFields = [
  {
    fieldLabel: "Select a product to feature:", 
    fieldType: "dropdown",
    requiredField: true, 
    fieldOptions: {
      values: dropdownValues
    }
  }
];

// Output the final JSON object
return {
  json: {
    telegram_form: formFields
  }
};

// Get all filenames from "Code in JavaScript3"
const filenamesRaw = $('Code in JavaScript3').first().json.filenames;

// Parse filenames — handle both array and comma-separated string
let filenamesArray = Array.isArray(filenamesRaw)
  ? filenamesRaw
  : filenamesRaw.split(',').map(f => f.trim());

// Strip file extensions and get clean names
const cleanedFilenames = filenamesArray.map(f => f.replace(/\.[^/.]+$/, '').trim());

if (cleanedFilenames.length === 0) {
  throw new Error('No filenames found to choose from.');
}

// Pick one at random
const randomName = cleanedFilenames[Math.floor(Math.random() * cleanedFilenames.length)];

return [{ json: { selectedProduct: randomName } }];

// Grab the incoming JSON data from whichever node is directly connected
const incomingData = $input.first().json;

let chosenProduct = "No product found";

// Option 1: From the Telegram custom form response (Dropdown)
if (incomingData.data && incomingData.data['Select a product to feature:']) {
  chosenProduct = incomingData.data['Select a product to feature:'];
} 
// Option 2: From the Random Product Selector node
else if (incomingData.selectedProduct) {
  chosenProduct = incomingData.selectedProduct;
}
// Option 3: From the 'Send message and wait for response' node ('File Name')
else {
  // Check if it's sitting right in the direct incoming data first
  if (incomingData.data && incomingData.data['File Name']) {
    chosenProduct = incomingData.data['File Name'];
  } else {
    // If not, safely check the specific node history using optional chaining
    try {
      const waitNodeData = $('Send message and wait for response').first()?.json?.data;
      if (waitNodeData && waitNodeData['File Name']) {
        chosenProduct = waitNodeData['File Name'];
      }
    } catch (error) {
      // If that node didn't execute on this path, ignore and do nothing
    }
  }
}

// Strip the file extension (e.g., .png, .jpg) if one exists
if (chosenProduct !== "No product found") {
  chosenProduct = chosenProduct.replace(/\.[^/.]+$/, "");
}

// Output the final consolidated variable
return {
  json: {
    product: chosenProduct
  }
};

// Get all items from the Read/Write Files node
const items = $input.all();

// Extract just the filenames and join them with commas
const filenames = items.map(item => item.json.fileName).join(', ');

return {
  json: {
    filenames: filenames
  }
};

// Fetch the 'product' variable directly from the node exactly named "Product"
const fullFilename = $('Product').first().json.product || "";

// Find the position of the last dot in the string
const lastDotIndex = fullFilename.lastIndexOf('.');

let cleanName = fullFilename;

// If a dot exists, slice the string to keep only the part before the last dot
if (lastDotIndex !== -1) {
  cleanName = fullFilename.substring(0, lastDotIndex);
}

// Output the clean name 
return {
  json: {
    clean_product_name: cleanName
  }
};

