parameters.jsCode:
const results = [];

for (const item of $input.all()) {
  try {
    // 1. Grab the raw response string from Ollama
    let rawResponse = item.json.response || "";

    // 2. Strip markdown formatting just in case
    let cleanedText = rawResponse.replace(/```json/g, '').replace(/```/g, '').trim();

    // 3. Assume the LLM gave us plain text by default
    let extractedSentence = cleanedText;

    // 4. Check if it might actually be JSON (starts with a bracket)
    if (cleanedText.startsWith('{') || cleanedText.startsWith('[')) {
        try {
            const parsedData = JSON.parse(cleanedText);
            // Grab the script/prompt, or fallback to the first value
            extractedSentence = parsedData.script || parsedData.prompt || Object.values(parsedData)[0];
        } catch (e) {
            // If JSON parsing fails, quietly stick with the raw text
        }
    }

    // 5. COMFYUI SANITIZATION
    // Clean up characters that crash ComfyUI's JSON parser
    if (typeof extractedSentence === 'string') {
        extractedSentence = extractedSentence
            // Replace all double quotes with single quotes
            .replace(/"/g, "'") 
            // Remove actual line breaks
            .replace(/\n/g, ' ') 
            // Remove carriage returns
            .replace(/\r/g, '')  
            // Remove literal escaped newlines (e.g., "\n" printed as text)
            .replace(/\\n/g, ' ') 
            // Clean up double spaces caused by removing newlines
            .replace(/\s+/g, ' ') 
            .trim();
    }

    // 6. Map to your output variable
    // Note: I named this raw_output because your ComfyUI node 111 looks for $('parser6').last().json.raw_output
    const cleanedItem = {
      "raw_output": extractedSentence 
    };

    results.push({ json: cleanedItem });

  } catch (error) {
    // Failsafe: Catch any broken JSON without crashing the workflow
    results.push({
      json: {
        error: "Failed to parse LLM JSON",
        details: error.message,
        raw_output: item?.json?.response || "Unknown Error"
      }
    });
  }
}

return results;

