// Code node that keeps only the latest (newest) binary item based on file modification time or order

// Get all items from the previous node
const items = $input.all();

// Sort items by file name or date in your desired order
// If filenames increment numerically, sort by that:
items.sort((a, b) => {
  const getNum = name => parseInt(name.match(/\d+/)?.[0] || 0, 10);
  return getNum(b.json.fileName) - getNum(a.json.fileName);
});

// Keep only the latest one
const newest = items[0];

// Return only that one
return [newest];

const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

// true  = adds a bottoms clause
// false = top only
const INCLUDE_BOTTOMS = true;

// 'gesture'      = free hand in a relaxed talking-style pose
// 'out_of_frame' = free hand rests low and out of frame, only the camera arm shows
const HAND_MODE = 'gesture';

const hair = [
  'dark brown', 'light brown', 'chestnut brown', 'espresso brown', 'soft black',
  'jet black', 'sandy blonde', 'dirty blonde', 'ash brown', 'warm brown',
  'dark blonde', 'golden brown', 'medium brown', 'short black', 'wavy dark brown'
];

const eyes = [
  'hazel', 'light blue', 'icy blue', 'deep blue', 'gray-blue', 'steel gray', 'green',
  'emerald green', 'green-hazel', 'honey hazel', 'amber',
  'light brown', 'warm brown', 'dark brown'
];

const colors = [
  'white', 'black', 'cream', 'sage green', 'olive green', 'baby blue',
  'navy', 'charcoal gray', 'burgundy', 'heather gray',
  'forest green', 'soft yellow', 'red', 'chocolate brown', 'powder blue', 'teal'
];

// clothes better suited for a male influencer
const garments = [
  'fitted crew-neck t-shirt',
  'fitted long-sleeve crew-neck shirt',
  'fine-knit crew-neck sweater',
  'quarter-zip pullover zipped up neatly',
  'zip-up track jacket zipped to the upper chest',
  'fitted polo shirt',
  'lightweight knit polo',
  'casual button-up shirt with the top button open',
  'premium hoodie',
  'fitted mock-neck top',
  'minimalist bomber jacket over a fitted t-shirt',
  'clean oversized t-shirt'
];

const bottoms = [
  'black slim-fit jeans',
  'dark-wash slim-fit jeans',
  'black tailored trousers',
  'charcoal tailored trousers',
  'navy tailored trousers',
  'dark olive trousers',
  'black straight-leg pants',
  'dark gray straight-leg trousers'
];

const interiors = [
  'cream white', 'black', 'cognac brown', 'ivory', 'burgundy red', 'dove gray',
  'caramel', 'chocolate brown', 'two-tone black and cream', 'navy blue',
  'saddle brown', 'two-tone gray and black'
];

// relaxed talking hand poses
const gestures = [
  'His other hand rests lightly near his chest with relaxed fingers, as if he is explaining something.',
  'His other hand is loosely raised at chest height in a casual talking gesture, fingers relaxed and together.',
  'His other hand rests near his jawline with relaxed fingers, as if thinking while he talks.',
  'His other hand is half-open at chest height with the palm angled inward in a natural conversational gesture.',
  'His other hand lightly adjusts his collar with relaxed, natural finger placement.'
];

const outOfFrameHand =
  'His other hand rests low, outside the frame, so only the forearm and sleeve of the camera arm are visible.';

// never repeat the same look (persists on active/production runs)
const store = $getWorkflowStaticData('global');
const used = new Set(store.usedLooks || []);

let look, key, tries = 0;
do {
  look = {
    hair: pick(hair),
    eyes: pick(eyes),
    color: pick(colors),
    garment: pick(garments),
    interior: pick(interiors)
  };
  if (INCLUDE_BOTTOMS) look.bottom = pick(bottoms);
  key = Object.values(look).join('|');
  tries++;
} while ((used.has(key) || (INCLUDE_BOTTOMS && look.bottom.includes(look.color))) && tries < 100);

used.add(key);
store.usedLooks = Array.from(used).slice(-5000);

const outfit = INCLUDE_BOTTOMS
  ? `a stylish ${look.color} ${look.garment} with ${look.bottom}`
  : `a stylish ${look.color} ${look.garment}`;

const hand = HAND_MODE === 'out_of_frame' ? outOfFrameHand : pick(gestures);

const TEMPLATE = `Tightly framed close-up vertical 9:16 smartphone selfie-style photo of a handsome 24 year old man with [HAIR] hair, framed from the waist up, sitting in the passenger seat of a luxury car, filming himself with the front camera. He is attractive but realistic, with a defined jawline, clear healthy skin with natural texture, well-groomed features, and expressive [EYES] eyes looking directly into the lens. He is mid-sentence, mouth slightly open, with the relaxed confident energy of a male influencer making a TikTok or Instagram story. One of his arms stretches out toward the camera to take the selfie, with only the forearm and sleeve visible at the edge of the frame. [HAND] He wears [OUTFIT] and subtle understated accessories such as a simple watch or chain. Interior: [INTERIOR] leather seats, premium stitched dashboard, panoramic sunroof, ambient lighting, clearly a high-end car like a Mercedes S-Class or Porsche Cayenne. Soft natural daylight coming through the windows, warm tones, shallow depth of field, authentic TikTok UGC look, close front-camera framing slightly below eye level, shot on an iPhone front camera, realistic skin texture with visible pores, subtle phone-camera grain, photorealistic.`;

const final_prompt = TEMPLATE
  .replace('[HAIR]', look.hair)
  .replace('[EYES]', look.eyes)
  .replace('[HAND]', hand)
  .replace('[OUTFIT]', outfit)
  .replace('[INTERIOR]', look.interior);

return [{
  json: {
    ...look,
    outfit,
    hand,
    final_prompt,
    seed: Math.floor(Math.random() * 1e15)
  }
}];

