// Each item contains: sentence, sentence_number.

const scripts = [
  // Script 1: Everyday cologne
  [
    "Guys, if you're looking for a new everyday cologne, I definitely recommend trying this one.",
    "It has a really clean, fresh scent that's easy to wear throughout the entire day.",
    "I like that it's noticeable without being too strong or overpowering when you put it on.",
    "If you want to check it out for yourself, I've linked it right here."
  ],

  // Script 2: Going out
  [
    "If you need a good cologne for going out, this is one I'd recommend checking out.",
    "It has a nice masculine scent with a fresh finish that works really well for evenings.",
    "I think it's a great option when you want something a little different from your everyday fragrance.",
    "You can find this cologne in the TikTok Shop link right here if you're interested."
  ],

  // Script 3: Simple recommendation
  [
    "Guys, I wanted to show you this cologne because I think it's a really solid option.",
    "The fragrance has a fresh, slightly warm scent that makes it pretty versatile for different occasions.",
    "It's the kind of cologne I would wear to work, dinner, or just going out.",
    "If that sounds like something you'd like, you can check it out through the link below."
  ],

  // Script 4: Cologne collection
  [
    "If you're trying to build up your cologne collection, take a look at this fragrance.",
    "It has a clean masculine scent that would fit really well into a daily rotation.",
    "I like fragrances that are easy to wear, and this one fits that style perfectly.",
    "I've put the link right here if you want to see the details or pick one up."
  ],

  // Script 5: First cologne recommendation
  [
    "If you're getting into colognes and don't know where to start, check this one out.",
    "It has a fresh and clean scent that makes it a versatile option for everyday use.",
    "You don't need a huge fragrance collection to find something that works for your style.",
    "If you're interested in this one, I've linked it right here so you can take a look."
  ]
];

const chosen = scripts[Math.floor(Math.random() * scripts.length)];

return chosen.map((sentence, i) => ({
  json: {
    sentence,
    sentence_number: i + 1
  }
}));

